package lv.venta.irrigation.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity public class IrrigationAlert { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String sensorId; private String zoneName; private String alertType; private String message; private String severity; private boolean acknowledged; private LocalDateTime createdAt;
 public IrrigationAlert(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getSensorId(){return sensorId;} public void setSensorId(String v){sensorId=v;} public String getZoneName(){return zoneName;} public void setZoneName(String v){zoneName=v;} public String getAlertType(){return alertType;} public void setAlertType(String v){alertType=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getSeverity(){return severity;} public void setSeverity(String v){severity=v;} public boolean isAcknowledged(){return acknowledged;} public void setAcknowledged(boolean v){acknowledged=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
